import {VikingOrdinaryAward} from './VikingRules';

/** Persistent progress is separate from the per-round destruction charge.
 * Pattern geometry is supplied from a researched level definition; no generic
 * mask or unverified god rotation is invented by this reducer. */
export interface VikingProgress {
 pattern:number[];
 cleared:number[];
 runes:number[];
 growingBonus:number;
}
export interface VikingProgressChange {
 before:VikingProgress;
 after:VikingProgress;
 newlyCleared:number[];
 newlyCollectedRunes:number[];
 growth:number;
 patternComplete:boolean;
 valhallaEligible:boolean;
}
function cellsValid(cells:readonly number[]){return cells.every(c=>Number.isInteger(c)&&c>=0&&c<49)&&new Set(cells).size===cells.length;}
function snapshot(state:VikingProgress):VikingProgress{return {...state,pattern:[...state.pattern],cleared:[...state.cleared],runes:[...state.runes]};}
/** Apply one displayed win batch exactly once. The 12% contribution is a meter
 * increment, not a deduction or extra payout. Only symbol awards enter here;
 * wheel awards and already-multiplied final totals must not be fed back in. */
export function vikingRecordSymbolWins(state:VikingProgress,wins:readonly VikingOrdinaryAward[]):VikingProgressChange {
 if(!state.pattern.length||!cellsValid(state.pattern)||!cellsValid(state.cleared)
  ||state.cleared.some(c=>!state.pattern.includes(c))
  ||new Set(state.runes).size!==state.runes.length||state.runes.some(s=>!Number.isInteger(s)||s<4||s>8)
  ||!Number.isFinite(state.growingBonus)||state.growingBonus<0)throw Error('Invalid Viking persistent progress');
 for(const win of wins){
  if(!Number.isInteger(win.symbol)||win.symbol<0||win.symbol>8||!cellsValid(win.cells)||win.cells.length<5
   ||!Number.isFinite(win.amount)||win.amount<0)throw Error('Invalid Viking symbol award');
 }
 const before=snapshot(state),cleared=new Set(state.cleared),runes=new Set(state.runes);
 const pattern=new Set(state.pattern);
 for(const win of wins){
  win.cells.forEach(cell=>{if(pattern.has(cell))cleared.add(cell);});
  if(win.symbol>=4)runes.add(win.symbol);
 }
 const growth=wins.reduce((sum,w)=>sum+w.amount,0)*.12;
 const after:VikingProgress={pattern:[...state.pattern],cleared:[...Array.from(cleared)].sort((a,b)=>a-b),runes:[...Array.from(runes)].sort((a,b)=>a-b),growingBonus:state.growingBonus+growth};
 const patternComplete=after.cleared.length===after.pattern.length;
 return {before,after,newlyCleared:after.cleared.filter(c=>!state.cleared.includes(c)),newlyCollectedRunes:after.runes.filter(s=>!state.runes.includes(s)),growth,patternComplete,valhallaEligible:patternComplete&&after.runes.length>0};
}
