import {LegacyAward,LEGACY_ALTAR,LEGACY_LINES,LEGACY_LINE_PAYS,legacyBaseAwards,legacyFreeSpins} from './LegacyRules';

export interface LegacyExpansion {
 symbol:number;reels:number[];before:number[];after:number[];awards:LegacyAward[];payout:number;
}
export interface LegacyRound {
 opening:number[];board:number[];selected:number[];baseAwards:LegacyAward[];
 expansions:LegacyExpansion[];awards:LegacyAward[];payout:number;freeSpinsAdded:number;
}
function validateSelection(selected:readonly number[]){
 if(selected.length>9||new Set(selected).size!==selected.length||selected.some(n=>!Number.isInteger(n)||n<0||n>=9))throw Error('Invalid Legacy selection');
}
/** Dedicated round draft. Each expansion is determined from the landed board,
 * never from a previous animation's replacement symbols. Presentation order is
 * explicit input; source multi-selection ordering still needs playback review.
 * A separate before/after per symbol lets the UI restore the landed board
 * between phases, rather than overwriting all selected types with one wildcard.
 */
export function legacyRound(board:readonly number[],bet:number,selected:readonly number[]=[],limit=Infinity):LegacyRound{
 validateSelection(selected);
 if(limit!==Infinity&&(!Number.isSafeInteger(limit)||limit<0))throw Error('Invalid Legacy payout budget');
 const raw=legacyBaseAwards(board,bet),opening=[...board],awards:LegacyAward[]=[];let remaining=limit;
 const settle=(award:LegacyAward)=>{
  const next={...award,cells:[...award.cells],amount:Math.min(remaining,award.amount)};
  remaining-=next.amount;if(next.amount>0)awards.push(next);return next;
 };
 const baseAwards=raw.map(settle).filter(a=>a.amount>0),expansions:LegacyExpansion[]=[];
 for(const symbol of selected){
  if(remaining===0)break;
  // Only the selected regular symbol causes expansion. An altar substitutes in
  // normal line awards but does not turn itself into an extra expansion reel.
  const reels=Array.from({length:5},(_,col)=>col).filter(col=>opening.some((value,cell)=>cell%5===col&&value===symbol));
  const multiple=(LEGACY_LINE_PAYS[symbol][reels.length-1]||0)/10;
  if(!multiple)continue;
  const before=[...opening],after=[...opening];
  for(const col of reels)for(let row=0;row<3;row++)after[row*5+col]=symbol;
  const phaseAwards=LEGACY_LINES.map((cells,line)=>settle({line,symbol,cells:cells.filter(cell=>reels.includes(cell%5)),multiple,amount:Math.round(bet*multiple)})).filter(a=>a.amount>0);
  expansions.push({symbol,reels,before,after,awards:phaseAwards,payout:phaseAwards.reduce((sum,a)=>sum+a.amount,0)});
 }
 return{opening,board:[...(expansions.length?expansions[expansions.length-1].after:opening)],selected:[...selected],baseAwards,expansions,awards,payout:awards.reduce((sum,a)=>sum+a.amount,0),freeSpinsAdded:legacyFreeSpins(opening.filter(symbol=>symbol===LEGACY_ALTAR).length)};
}

/** Choose an additional regular symbol without removing earlier selections.
 * Once all nine are active no tenth symbol can be invented. The game loop
 * still awards retrigger spins, following the current official unlimited rule. */
export function legacyAddSelection(selected:readonly number[],rng:()=>number):number[]{
 validateSelection(selected);
 const available=Array.from({length:9},(_,i)=>i).filter(i=>!selected.includes(i));
 if(!available.length)return[...selected];
 const roll=rng();if(!Number.isFinite(roll)||roll<0||roll>=1)throw Error('Invalid Legacy RNG');
 return[...selected,available[Math.floor(roll*available.length)]];
}
