import type {SpinResult,Win} from './SlotMain';
export const SUBMARINE_ART=['rank_10','rank_j','rank_q','rank_k','rank_a','cook','radio_operator','engineer','periscope_operator','captain','nudge_wild','ways_device','bomb_wild','sonar','periscope_wild','torpedo_wild'];
export const SUBMARINE_EFFECT_ART=['submarine','target_ship','blast','torpedo_trail'];
export const submarineSymbol=(name:string)=>'boot-camp-x-'+name;
export const SUBMARINE_HEIGHTS=[2,3,4,4,3,2];
export const submarineVisible=(cell:number)=>Number.isInteger(cell)&&cell>=0&&cell<24&&Math.floor(cell/6)>=4-SUBMARINE_HEIGHTS[cell%6];
export interface SubmarineState {remaining:number;played:number;multiplier:number;bays:number[]}
export interface SubmarinePrize {symbol:string;cells:number[];baseAmount:number}
export interface SubmarineTurn {board:string[];torpedoes:number[];regular:SubmarinePrize[];launched:SubmarinePrize[];revealSymbol?:string;scatters?:number[]}
export interface SubmarineLoad {cell:number;bay:number;before:number;after:number}
export interface SubmarineLaunch {values:number[];beforeMultiplier:number;afterMultiplier:number;reveals:{cell:number;symbol:string;count:number}[];wins:Win[]}
export interface SubmarineStage {before:SubmarineState;consumed:SubmarineState;after:SubmarineState;board:string[];regular:Win[];loads:SubmarineLoad[];launch?:SubmarineLaunch;scatters:number[];added:number}
export interface SubmarinePlayback {initial:SubmarineState;stages:SubmarineStage[];final:SubmarineState;triggerBoard:string[]}
const copy=(s:SubmarineState):SubmarineState=>({...s,bays:[...s.bays]});
/** Wolf Pack event replay. Paytable outcomes and post-launch placement are
 * explicit audit inputs; this is deliberately not a natural spin generator. */
export function submarineSequence(triggerBoard:string[],turns:SubmarineTurn[],bet:number):SpinResult{
 if(!Number.isSafeInteger(bet)||bet<1)throw Error('Invalid submarine bet');
 const validateBoard=(board:string[])=>{if(board.length!==24||board.some((id,i)=>submarineVisible(i)?!SUBMARINE_ART.some(name=>submarineSymbol(name)===id):id!==submarineSymbol('void')))throw Error('Invalid submarine geometry or symbol');};
 validateBoard(triggerBoard);
 const trigger=triggerBoard.flatMap((id,cell)=>id===submarineSymbol('sonar')?[cell]:[]);
 if(trigger.length!==4||new Set(trigger.map(cell=>cell%6)).size!==4||trigger.some(cell=>cell%6<1||cell%6>4))throw Error('Wolf Pack requires four inner-reel sonars');
 const initial:SubmarineState={remaining:8,played:0,multiplier:1,bays:[0,0,0,0]};let state=copy(initial);const stages:SubmarineStage[]=[],wins:Win[]=[];
 const prizes=(items:SubmarinePrize[],multiplier:number)=>items.map(item=>{
  if(!Number.isSafeInteger(item.baseAmount)||item.baseAmount<1||!item.cells.length||item.cells.some(cell=>!submarineVisible(cell)))throw Error('Invalid submarine award');
  const amount=item.baseAmount*multiplier;if(!Number.isSafeInteger(amount))throw Error('Submarine award overflow');
  const win:Win={line:-1,symbol:item.symbol,cells:[...item.cells],amount,multiplier};wins.push(win);return win;
 });
 for(const turn of turns){
  if(!state.remaining)throw Error('Submarine sequence already ended');validateBoard(turn.board);
  const before=copy(state),consumed=copy(state);consumed.remaining--;consumed.played++;state=copy(consumed);
  const regular=prizes(turn.regular,state.multiplier),loads:SubmarineLoad[]=[];
  if(new Set(turn.torpedoes).size!==turn.torpedoes.length)throw Error('Duplicate torpedo');
  for(const cell of turn.torpedoes){
   const bay=cell%6-1;if(!submarineVisible(cell)||bay<0||bay>3||turn.board[cell]!==submarineSymbol('torpedo_wild'))throw Error('Invalid torpedo ownership');
   const old=state.bays[bay];state.bays[bay]=old?Math.min(9,old+1):2;loads.push({cell,bay,before:old,after:state.bays[bay]});
  }
  let launch:SubmarineLaunch|undefined;
  if(state.bays.every(value=>value>0)){
   if(!SUBMARINE_ART.slice(0,10).some(name=>submarineSymbol(name)===turn.revealSymbol))throw Error('Missing regular torpedo reveal');
   launch={values:[...state.bays],beforeMultiplier:state.multiplier,afterMultiplier:++state.multiplier,reveals:state.bays.map((count,bay)=>({cell:19+bay,symbol:bay===0||bay===3?turn.revealSymbol!:submarineSymbol('torpedo_wild'),count})),wins:prizes(turn.launched,state.multiplier)};
   state.bays=[0,0,0,0];
  }else if(turn.launched.length)throw Error('Unlaunched torpedo cannot pay');
  const scatters=[...(turn.scatters||[])];if(new Set(scatters).size!==scatters.length||scatters.some(cell=>!submarineVisible(cell)||cell%6<1||cell%6>4||turn.board[cell]!==submarineSymbol('sonar')))throw Error('Invalid submarine retrigger');
  const added=scatters.length*2;state.remaining+=added;
  stages.push({before,consumed,after:copy(state),board:[...turn.board],regular,loads,launch,scatters,added});
 }
 if(state.remaining)throw Error('Submarine sequence ended before remaining spins');
 const board=[...stages[stages.length-1].board];return {bet,board,wins,payout:wins.reduce((n,w)=>n+w.amount,0),submarineFeature:{initial,stages,final:copy(state),triggerBoard:[...triggerBoard]}};
}
