import {drawThreeGateBoard} from './ConditionalGateBoard';
import {ExpansionSlot,expansionCells as cells,Geometry} from './ExpansionCore';
/** Local 15-line interpretation of Wild Honey Jackpot's winning-bear prizes. */
export class BearHoneySlot extends ExpansionSlot {
 constructor(spec:ConstructorParameters<typeof ExpansionSlot>[0]){super(spec);this.paylines.splice(15);}
 get bonusCalibrationKey(){return this.config.id+':expansion-v2-hives';}
 private pool(col:number){return this.config.symbols.filter(s=>s.weight>0&&(col>=2||s.id!==this.id('wild')));}
 private weighted(rng:()=>number,pool:{id:string;weight:number}[]){let roll=rng()*pool.reduce((n,s)=>n+s.weight,0);for(const s of pool){roll-=s.weight;if(roll<0)return s.id;}return pool[pool.length-1].id;}
 draw(bet:number,rng:()=>number,g:Geometry=this.geometry){if(!this.bets.includes(bet))throw Error('Invalid bet');const board:string[]=[];for(let c=0;c<g.columns*g.rows;c++){let pool=this.pool(c%5);if(board.some((s,i)=>i%5===c%5&&s===this.id('scatter')))pool=pool.filter(s=>s.id!==this.id('scatter'));board.push(this.weighted(rng,pool));}return board;}
 prepareBonusPurchase(bet:number,rng:()=>number){
  if(!this.bets.includes(bet))throw Error('Invalid bet');
  const board=drawThreeGateBoard(col=>this.pool(col),this.id('scatter'),rng,(r,p)=>this.weighted(r,p));
  return this.purchaseFromResult(this.play(board,bet,rng));
 }
 private honeyRound(board:string[],bet:number,rng:()=>number){
  const hit=this.hit(board,bet),used=new Set(hit.wins.flatMap(w=>w.cells));
  const bears=cells(board,this.id('wild')).filter(c=>c%5>=2),awards=bears.map(cell=>{const col=cell%5,roll=rng(),multiple=col===2?(roll<.85?1:2):col===3?(roll<.8?3:5):(roll<.75?8:roll<.95?15:roll<.995?30:100);const frame=this.prize(board,bet,multiple,[cell],col===4&&multiple>=30?'꿀단지 고정 잭팟':'당첨 곰 상금');return{cell,win:frame.wins[0],used:used.has(cell)};});
  const visible=awards.map(({cell,win})=>({cell,win})),frames=[this.frame(board,'reels','3~5릴 곰 · 오른쪽 릴 상금 증가',[],{coinAwards:visible}),hit];
  hit.coinAwards=visible;
  const paid=awards.filter(a=>a.used);if(paid.length)frames.push(this.frame(board,'trigger','당첨에 참여한 곰 상금 공개',paid.map(a=>a.cell),{coinAwards:visible}),this.frame(board,'win','곰 상금 · 각 곰 한 번 지급',paid.map(a=>a.cell),{coinAwards:visible,wins:paid.map(a=>a.win)}));
  for(const f of frames)if(f.coinAwards)f.coinAwards=visible;
  return this.round(bet,frames);
 }
 play(board:string[],bet:number,rng:()=>number){const base=this.honeyRound(board,bet,rng),gates=cells(board,this.id('scatter')),count=new Set(gates.map(c=>c%5)).size;if(count<3)return this.finish([base]);return this.freeFromRound(base,bet,rng,(count-2)*5,b=>{const round=this.honeyRound(b,bet,rng),n=new Set(cells(b,this.id('scatter')).map(c=>c%5)).size;if(n>=3)round.freeSpinsAdded=(n-2)*5;return round;},gates);}
}
