/** The single-symbol reel shares the minimum normal-spin anticipation. */
export const CONTRACT_REEL_SECONDS=1.25;
export const CONTRACT_CHOICE_HOLD=.04;
export const CONTRACT_WIN_SECONDS=.18;
export const contractColors=['#ff724c','#55dfff','#c781ff','#a6e7ff','#ff4862'];
export function contractChoiceLayout(width:number,height:number){
 const cardWidth=Math.min(width-40,540),gap=20,side=Math.min(192,(cardWidth-68)/2),cardHeight=side+178;
 const x=(width-cardWidth)/2,y=(height-cardHeight)/2;
 return {x,y,cardWidth,cardHeight,side,gap,left:x+(cardWidth-side*2-gap)/2,top:y+108};
}
