import {Node,UITransform,Graphics,Color,Label} from 'cc';
import {i18n} from '../services/Localization';
import {gameAudio} from '../services/GameAudio';

export const MISSION_BANNER_ENTER_SECONDS=.48;
export const MISSION_BANNER_STACK_RATE=8;

/** Presentation only; independent lifetimes survive GameUI rebuilds. */
export class MissionBanners {
 private root:Node;private cards:{node:Node;age:number;y:number;particles:Node[]}[]=[];
 private pending:string[]=[];private gap=0;
 constructor(parent:Node){this.root=new Node('Mission completion banners');this.root.layer=parent.layer;parent.addChild(this.root);}
 add(name:string){this.pending.push(name);}
 update(dt:number,width:number,height:number,top:number){
  dt=Math.max(0,Math.min(dt,.1));this.gap-=dt;
  const w=Math.min(580,width-40),h=86;
  if(this.pending.length&&this.gap<=0&&this.cards.length<3){
   const n=new Node('Mission complete');n.layer=this.root.layer;this.root.addChild(n);n.addComponent(UITransform).setContentSize(w,h);
   const g=n.addComponent(Graphics);g.fillColor=new Color('#263b42');g.roundRect(-w/2,-h/2,w,h,10);g.fill();g.strokeColor=new Color('#efc878');g.lineWidth=3;g.roundRect(-w/2+2,-h/2+2,w-4,h-4,8);g.stroke();g.fillColor=new Color('#efc878');g.rect(-w/2+8,-h/2+10,5,h-20);g.fill();
   const text=(value:string,y:number,size:number,color:string)=>{const child=new Node('Mission banner text');child.layer=n.layer;n.addChild(child);child.setPosition(12,y);const label=child.addComponent(Label);label.string=value;label.fontFamily=i18n.fontFamily;label.fontSize=size;label.lineHeight=size+4;label.isBold=true;label.color=new Color(color);label.horizontalAlign=Label.HorizontalAlign.LEFT;label.verticalAlign=Label.VerticalAlign.CENTER;label.overflow=Label.Overflow.SHRINK;label.enableWrapText=false;child.getComponent(UITransform)!.setContentSize(w-64,32);};
   text(i18n.t('quest.bannerComplete'),20,19,'#efc878');text(this.pending.shift()!,-15,25,'#fff4d5');
   const particles:Node[]=[];for(let i=0;i<16;i++){const p=new Node('Mission clear sparkle');p.layer=n.layer;n.addChild(p);const paint=p.addComponent(Graphics);paint.fillColor=new Color(i%2?'#fff2bd':'#70e9c4');paint.rect(-3,-3,6,6);paint.fill();particles.push(p);}
   this.cards.unshift({node:n,age:0,y:0,particles});this.gap=.45;gameAudio.cue('finish');
  }
  this.cards.forEach((c,index)=>{
   c.age+=dt;c.y+=(index*(h+10)-c.y)*Math.min(1,dt*MISSION_BANNER_STACK_RATE);
   const enter=Math.min(1,c.age/MISSION_BANNER_ENTER_SECONDS),exit=Math.max(0,Math.min(1,(c.age-3.32)/.32)),slide=1-(1-enter)**3-exit*exit;
   c.node.setPosition(-width/2-w/2-12+(w+32)*slide,height/2-top-h/2-c.y);
   c.particles.forEach((p,i)=>{const t=c.age-.1,a=i/16*Math.PI*2;p.active=t>=0&&t<.85;p.setPosition(Math.cos(a)*(30+t*110),Math.sin(a)*(12+t*45));p.angle=t*160+i*21;});
  });
  this.cards=this.cards.filter(c=>{if(c.age<3.64)return true;c.node.destroy();return false;});
  if(this.root.parent)this.root.setSiblingIndex(this.root.parent.children.length-1);
 }
 destroy(){this.pending=[];this.cards=[];this.root.destroy();}
}
