import {buyBonusResult} from './BonusBuy';
import {BalloonBundleSlot} from './BalloonBundleSlot';import {socialSeed} from './Social1921Rules';
export function balloonBundleAudit(params:URLSearchParams){const slot=new BalloonBundleSlot(),outcome=params.get('audit-outcome')||'pop';slot.demoSpin=bet=>{const rng=socialSeed(470001);for(let i=0;i<300000;i++){const r=slot.spin(bet,rng),f=(r.rounds?.[0]||r).balloonFeature!,match=outcome==='no-win'?!r.rounds&&!r.payout:outcome==='multi-win'?!r.rounds&&f.lineWins.length>1:outcome==='retrigger'?r.rounds?.some(q=>q.freeSpinsAdded):outcome==='bonus'?r.rounds:outcome==='ticket'?!r.rounds&&f.pops.some(p=>p.multiplier>1):outcome==='free-mark'?f.pops.some(p=>p.freeSpins>0):!r.rounds&&f.pops.some(p=>p.count===3);if(match)return r;}throw Error('Balloon fixture unavailable');};slot.bonusDemoSpin=bet=>{if(outcome==='bought'){const rng=socialSeed(471428);for(let i=0;i<500;i++){const r=buyBonusResult(slot,bet,rng);if(r.rounds!.length<20&&r.rounds!.some(q=>q.balloonFeature?.pops.some(p=>p.win.amount>0)))return r;}throw Error('Bought balloon pop fixture unavailable');}const rng=socialSeed(470101);for(let i=0;i<300000;i++){const r=slot.spin(bet,rng);if(r.rounds&&r.rounds.length<20)return r;}throw Error('Balloon bonus unavailable');};return slot;}
