/** Exact at-least-three-hive conditional draw for five reels with one gate per reel. */
export function drawThreeGateBoard(pool:(col:number)=>{id:string;weight:number}[],scatter:string,rng:()=>number,weighted:(rng:()=>number,pool:{id:string;weight:number}[])=>string){
  const q=Array.from({length:5},(_,c)=>{const p=pool(c);return 1-p.find(s=>s.id===scatter)!.weight/p.reduce((n,s)=>n+s.weight,0);});
  const masks=Array.from({length:32},(_,mask)=>({mask,weight:q.reduce((n,v,c)=>n*((mask>>c&1)?1-v**3:v**3),1)})).filter(v=>Array.from({length:5},(_,c)=>v.mask>>c&1).reduce((a,b)=>a+b,0)>=3);
  let roll=rng()*masks.reduce((n,v)=>n+v.weight,0),mask=masks[masks.length-1].mask;for(const item of masks){roll-=item.weight;if(roll<0){mask=item.mask;break;}}
  const board=Array<string>(15);for(let col=0;col<5;col++){const plain=pool(col).filter(s=>s.id!==scatter);let row=-1;if(mask>>col&1){let r=rng()*(1+q[col]+q[col]**2);row=2;for(let i=0;i<3;i++){r-=q[col]**i;if(r<0){row=i;break;}}}for(let i=0;i<3;i++)board[i*5+col]=i===row?scatter:weighted(rng,plain);}
 return board;
}
