/** Free hourly wheel. Visual sectors have equal angles, deliberately unequal odds. */
export const WHEEL_COOLDOWN_MS = 60 * 60 * 1000;
export const WHEEL_SECTOR_COUNT = 24;
export const WHEEL_SECTOR_DEGREES = 360 / WHEEL_SECTOR_COUNT;
const legacyAmounts = [10000,20,50,0,100,30,200,50,10,500,20,100,0,50,300,30,100,1000,20,50,0,200,30,100,5000,10,50,300,20,100,0,50,2000,30,200,500];
const amountsV2 = [10000,10,75,0,200,25,500,50,1500,100,300,40,5000,60,250,15,1000,125,400,20,2000,150,750,30];
const amountsV3 = amountsV2.map(coins=>coins*2);
const amounts = [20000,100,150,140,400,180,1000,220,3000,200,600,350,10000,120,500,450,2000,250,800,700,4000,300,1500,900];
// Favour mid-range rewards over the old concentration on very small amounts.
const relative = amounts.map((coins,index)=>index===0?0:coins<500?80:coins<2000?120:coins<10000?70:30);
const total=relative.reduce<number>((a,b)=>a+b,0),weights=relative.map((w,i)=>i===0?100:Math.floor(w*9900/total));
// Integer probability tickets: the maximum reward is exactly 100/10,000 (1%).
let remainder=10000-weights.reduce((a,b)=>a+b,0);
for(let i=1;remainder>0;i=i%23+1){weights[i]++;remainder--;}
export const WHEEL_SECTORS = amounts.map((coins,index)=>({index,coins,weight:weights[index]}));
export interface WheelReceipt {startedAt:number;index:number;coins:number;tableVersion?:2|3|4;doubled?:boolean;}
export interface HourlyWheelState {lastSpinAt:number;pending:WheelReceipt|null;}
export function newHourlyWheel():HourlyWheelState{return {lastSpinAt:0,pending:null};}
export function normalizeHourlyWheel(value:unknown):HourlyWheelState{
 const v=value as Partial<HourlyWheelState>|null;
 if(!v||!Number.isSafeInteger(v.lastSpinAt)||v.lastSpinAt!<=0)return newHourlyWheel();
 const p=v.pending;
 const table=p?.tableVersion===4?amounts:p?.tableVersion===3?amountsV3:p?.tableVersion===2?amountsV2:legacyAmounts;
 const valid=p&&p.startedAt===v.lastSpinAt&&Number.isInteger(p.index)&&table[p.index]===p.coins;
 // Existing pending awards keep the amount that was committed before the reward increase.
 const index=p?.tableVersion?p.index:amountsV2.indexOf(p?.coins??-1);
 return {lastSpinAt:v.lastSpinAt!,pending:valid&&index>=0?{startedAt:p.startedAt,index,coins:p.coins,...(p.tableVersion?{tableVersion:p.tableVersion}:{}),doubled:p.doubled===true}:null};
}
export function wheelWaitMs(state:HourlyWheelState,now=Date.now()){
 return state.lastSpinAt===0?0:Math.max(0,state.lastSpinAt+WHEEL_COOLDOWN_MS-now);
}
export function drawWheel(random=Math.random):number{
 const value=random();if(!Number.isFinite(value)||value<0||value>=1)throw Error('Invalid wheel random value');
 let ticket=Math.floor(value*10000);
 for(const sector of WHEEL_SECTORS){ticket-=sector.weight;if(ticket<0)return sector.index;}
 throw Error('Invalid wheel probability table');
}
/** Counterclockwise degree travel: sector index lands at the fixed twelve o’clock pointer. */
export function wheelTarget(index:number){if(!Number.isInteger(index)||index<0||index>=WHEEL_SECTOR_COUNT)throw Error('Invalid wheel sector');return 360*6+index*WHEEL_SECTOR_DEGREES;}
export const WHEEL_SPIN_SECONDS=9;
const smooth=(t:number)=>{t=Math.max(0,Math.min(1,t));return t*t*(3-2*t);};
/** Final peg tension either releases into the awarded sector or rocks back inside it. */
export function wheelTravel(seconds:number,target:number){
 if(seconds<=.3)return -7*Math.sin(Math.max(0,seconds)/.3*Math.PI/2);
 if(seconds>=WHEEL_SPIN_SECONDS)return target;
 const crosses=Math.round(target/WHEEL_SECTOR_DEGREES)%2===0;
 const approach=target+(crosses?-8.4:5.9),edge=target+(crosses?-7.65:7.2);
 if(seconds<5.9){const t=(seconds-.3)/5.6,eased=10*t*t-20*t*t*t+15*t**4-4*t**5;return -7+(approach+7)*eased;}
 if(seconds<7.1)return approach+(edge-approach)*smooth((seconds-5.9)/1.2);
 // The peg loads against the flapper, then barely moves before release.
 if(seconds<7.65)return edge+.10*Math.sin((seconds-7.1)/.55*Math.PI);
 const released=target+(crosses?-4.6:4.6);
 if(seconds<8.25)return edge+(released-edge)*smooth((seconds-7.65)/.6);
 return released+(target-released)*smooth((seconds-8.25)/.75);
}
/** Pointer bends at each physical sector boundary, including a slow final catch. */
export function wheelPointerAngle(angle:number){
 const phase=((angle+WHEEL_SECTOR_DEGREES/2)%WHEEL_SECTOR_DEGREES+WHEEL_SECTOR_DEGREES)%WHEEL_SECTOR_DEGREES;
 if(phase>12)return -30*smooth((phase-12)/3);
 if(phase<1.1)return -30*(1-smooth(phase/1.1));
 return 0;
}
/** A damped flapper, driven by peg contact, then free to rebound around its hinge. */
export function stepWheelPointer(state:{angle:number;velocity:number},from:number,to:number,dt:number){
 const steps=Math.max(1,Math.ceil(Math.max(0,dt)*240)),h=Math.max(0,dt)/steps;
 for(let i=1;i<=steps;i++){
  const contact=wheelPointerAngle(from+(to-from)*i/steps);
  state.velocity+=(-640*state.angle-24*state.velocity)*h;
  state.angle+=state.velocity*h;
  if(contact<0&&contact<state.angle){state.angle=contact;state.velocity=Math.min(0,state.velocity);}
  state.angle=Math.max(-34,Math.min(14,state.angle));
 }
 return state.angle;
}
