/** Case-insensitive nicknames; precomposed Hangul avoids alternate Unicode spellings. */
export function playerName(value:string){const display=value.normalize('NFC').trim();if(!/^[A-Za-z0-9가-힣ㄱ-ㅎㅏ-ㅣ_]{1,12}$/.test(display))throw Error('이름은 한글·영문·숫자·밑줄로 1–12자 입력해 주세요.');return {display,key:display.toLowerCase()};}
export function canUseName(owner:string|undefined,uid:string){return !owner||owner===uid;}
