export function winTier(payout:number,bet:number){
 const multiple=payout/bet;
 return multiple>=100?{title:'SENSATIONAL!',color:'#ff8dd8',rank:4}:multiple>=50?{title:'MEGA WIN!',color:'#bc9dff',rank:3}:multiple>=30?{title:'SUPER WIN!',color:'#72e8ef',rank:2}:multiple>=10?{title:'BIG WIN!',color:'#ffd46b',rank:1}:null;
}
